apiVersion: apps/v1
kind: Deployment
metadata: {name: vuoro-gateway, namespace: vuoro-system, labels: {app.kubernetes.io/name: vuoro-gateway}}
spec:
  replicas: 2
  selector:
    matchLabels: {app.kubernetes.io/name: vuoro-gateway}
  template:
    metadata:
      labels: {app.kubernetes.io/name: vuoro-gateway}
    spec:
      serviceAccountName: vuoro-gateway
      automountServiceAccountToken: false
      imagePullSecrets: [{name: vuoro-ghcr-pull}]
      securityContext: {runAsNonRoot: true, runAsUser: 65532, runAsGroup: 65532, fsGroup: 65532, seccompProfile: {type: RuntimeDefault}}
      containers:
        - name: gateway
          image: ghcr.io/bayleafwalker/vuoro-cloud@sha256:02b792fdf2324ad56ea3ae7a85e82c348b88ae00894bc2991c678f5b065875bf
          command: [vuoro-gateway]
          ports: [{name: http, containerPort: 8080}]
          env:
            - {name: VUORO_CLOUD_SERVICE_ROLE, value: gateway}
            # Verifies OAuth access tokens at /mcp (D-046); the public half only.
            - {name: VUORO_CLOUD_OAUTH_AS_PUBLIC_KEY_FILE, value: /var/run/vuoro/oauth-as-verification/oauth-as-public.pem}
            # Must match the tenant controller's value: off, /mcp answers 503
            # at once instead of timing out against a runtime without port 8081.
            - {name: VUORO_CLOUD_TENANT_MCP_EDGE, value: "true"}
            # DB role split (unit 1.5, G2a): connect as vuoro_gateway. Since G4
            # vuoro-gateway-runtime carries no VUORO_CLOUD_DATABASE_URL; this
            # entry is the gateway's only connection string.
            - {name: VUORO_CLOUD_DATABASE_URL, valueFrom: {secretKeyRef: {name: vuoro-gateway-db, key: VUORO_CLOUD_DATABASE_URL}}}
          envFrom: [{secretRef: {name: vuoro-gateway-runtime}}]
          readinessProbe: {httpGet: {path: /health/ready, port: http}}
          livenessProbe: {httpGet: {path: /health/live, port: http}}
          resources:
            requests: {cpu: 100m, memory: 192Mi}
            limits: {cpu: 500m, memory: 512Mi}
          securityContext:
            allowPrivilegeEscalation: false
            readOnlyRootFilesystem: true
            capabilities: {drop: [ALL]}
          volumeMounts:
            - {name: compatibility, mountPath: /app/config, readOnly: true}
            - {name: signing-key, mountPath: /var/run/vuoro/signing, readOnly: true}
            - {name: verification-key, mountPath: /var/run/vuoro/verification, readOnly: true}
            - {name: oauth-as-verification-key, mountPath: /var/run/vuoro/oauth-as-verification, readOnly: true}
      volumes:
        - {name: compatibility, configMap: {name: vuoro-compatibility}}
        - {name: signing-key, secret: {secretName: vuoro-gateway-signing-key}}
        - {name: verification-key, configMap: {name: vuoro-gateway-verification}}
        - {name: oauth-as-verification-key, configMap: {name: vuoro-oauth-as-verification}}
---
apiVersion: v1
kind: Service
metadata: {name: vuoro-gateway, namespace: vuoro-system, labels: {app.kubernetes.io/name: vuoro-gateway}}
spec:
  selector: {app.kubernetes.io/name: vuoro-gateway}
  ports: [{name: http, port: 8080, targetPort: http}]
---
apiVersion: v1
kind: ServiceAccount
metadata: {name: vuoro-gateway, namespace: vuoro-system}
automountServiceAccountToken: false
